CREATE TABLE "Payments" (
    "Id"                    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ReservationId"         INTEGER NOT NULL REFERENCES "Reservations" ("Id"),
    "Provider"              TEXT NOT NULL,
    "ProviderTransactionId" TEXT NULL,
    "Amount"                NUMERIC(10, 2) NOT NULL CHECK ("Amount" >= 0),
    "Currency"              TEXT NOT NULL,
    "Status"                TEXT NOT NULL CHECK ("Status" IN ('Pending', 'Succeeded', 'Failed')),
    "PaidAtUtc"             TIMESTAMPTZ NULL,
    "CreatedAtUtc"          TIMESTAMPTZ NOT NULL,
    CONSTRAINT "CK_Payments_PaidAt" CHECK (("Status" = 'Succeeded') = ("PaidAtUtc" IS NOT NULL))
);

CREATE INDEX "IX_Payments_ReservationId" ON "Payments" ("ReservationId");

-- Confirmed reservations: paid in full. Pending: a pending payment. Cancelled: a failed attempt.
INSERT INTO "Payments" ("ReservationId", "Provider", "ProviderTransactionId", "Amount", "Currency", "Status", "PaidAtUtc", "CreatedAtUtc")
SELECT r."Id",
       (ARRAY['Visa', 'PayPal', 'MobilePay'])[1 + (r."Id" % 3)],
       CASE r."Status" WHEN 'Pending' THEN NULL ELSE 'TXN-' || lpad(r."Id"::text, 6, '0') END,
       r."TotalPrice",
       'EUR',
       CASE r."Status" WHEN 'Confirmed' THEN 'Succeeded' WHEN 'Pending' THEN 'Pending' ELSE 'Failed' END,
       CASE r."Status" WHEN 'Confirmed' THEN now() END,
       now()
FROM "Reservations" r;

-- Reservation 8 also had an earlier failed attempt before the successful one.
INSERT INTO "Payments" ("ReservationId", "Provider", "ProviderTransactionId", "Amount", "Currency", "Status", "PaidAtUtc", "CreatedAtUtc")
SELECT "Id", 'Visa', 'TXN-FAILED-' || lpad("Id"::text, 6, '0'), "TotalPrice", 'EUR', 'Failed', NULL, now() - interval '5 minutes'
FROM "Reservations" WHERE "Id" = 8;
